# Let me check the "rightness" score of each 4-group
# Count how many 4s have a neighbor (N,S,E,W) that is also a 4

def count_neighbors(grid, r, c):
    """Count how many of the 4 neighbors are also 4"""
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == 4:
                count += 1
    return count

def count_total_neighbors_for_group(input_grid):
    """For each 4, count its 4-neighbors that are also 4. Sum across group."""
    all_4s = [(r, c) for r in range(16) for c in range(27) if input_grid[r][c] == 4]
    group_sums = {}
    for r, c in all_4s:
        group_sums[(r, c)] = count_neighbors(input_grid, r, c)
    return all_4s, group_sums

